#!/usr/bin/env bash
set -euo pipefail
git init -q -b main
git config user.email eval@example.com
git config user.name eval
mkdir -p .project src/api
cat > package.json <<"J"
{ "name": "ledger", "scripts": { "dev": "next dev -p 3100", "test": "vitest run" } }
J
echo 'export {}' > src/api/client.ts
cat > CLAUDE.md <<"MD"
# Claude Code Setup

## User Preferences

Language: Nederlands

## Project

<!-- GENERATED BY /setup - DO NOT EDIT MANUALLY -->

**Name**: {{PROJECT_NAME}}

## Project Context

Consult .project/ before grepping.

## Deploy runbook

- Deploys go through Vercel; run `pnpm db:migrate` locally first, the build does not migrate.
MD
cat > .project/project-seed.md <<"MD"
# ledger

Simple bookkeeping app for freelancers: log invoices and expenses, see quarterly VAT.
MD
cat > .project/backlog.json <<"J"
{ "schemaVersion": 2, "features": [
  { "name": "invoices", "status": "DONE", "description": "Create and list invoices." },
  { "name": "export-csv", "status": "TODO", "description": "Export a quarter's invoices and expenses as CSV for the accountant." },
  { "name": "verify-invoices-manual", "status": "TODO", "description": "Re-run deferred manual test(s) for invoices: e2e suite not yet green." }
] }
J
cat > .project/project-context.json <<"J"
{ "schemaVersion": 2, "learnings": [
  { "type": "pitfall", "summary": "The bank API returns amounts in cents as strings; parse with BigInt, never parseFloat.", "paths": ["src/api/client.ts"] },
  { "type": "pitfall", "summary": "De bank-API geeft bedragen in centen als strings; parse met BigInt, nooit parseFloat.", "paths": ["src/api/client.ts"] },
  { "type": "pitfall", "summary": "next build in a worktree fails when .project/archive is a symlink outside the root; remove it for the build.", "paths": [] }
] }
J
echo ".project/" > .gitignore
git add -A && git commit -qm init
